-- ReelStudio backend foundation
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.brand_settings (user_id uuid primary key references auth.users(id) on delete cascade, brand_name text not null default 'Adeel Raja', logo_storage_path text, watermark_position text not null default 'bottom-right' check (watermark_position in ('bottom-right','bottom-left','top-right','top-left')), watermark_size text not null default 'medium' check (watermark_size in ('small','medium','large')), watermark_opacity numeric(4,3) not null default 0.850 check (watermark_opacity between 0 and 1), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.connected_accounts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, platform text not null check (platform in ('facebook_page','instagram','youtube')), provider_account_id text not null, display_name text not null, access_token_ciphertext text, refresh_token_ciphertext text, token_expires_at timestamptz, granted_scopes text[] not null default '{}', connection_status text not null default 'connected' check (connection_status in ('connected','expired','revoked','error')), metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, platform, provider_account_id), unique(id, user_id));
create table if not exists public.media_assets (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, storage_path text not null, original_filename text not null, mime_type text not null, byte_size bigint not null check (byte_size > 0), duration_seconds numeric(12,3), width integer, height integer, processing_status text not null default 'uploaded' check (processing_status in ('uploaded','processing','ready','failed')), created_at timestamptz not null default now(), unique(user_id, storage_path), unique(id, user_id));
create table if not exists public.posts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, media_asset_id uuid references public.media_assets(id) on delete set null, caption text not null default '', hashtags text[] not null default '{}', keywords text[] not null default '{}', scheduled_at timestamptz, status text not null default 'draft' check (status in ('draft','scheduled','processing','published','partially_published','failed','cancelled')), timezone text not null default 'Asia/Karachi', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id, user_id));
create table if not exists public.post_targets (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, connected_account_id uuid not null references public.connected_accounts(id) on delete restrict, provider_post_id text, status text not null default 'pending' check (status in ('pending','queued','uploading','published','failed','skipped')), error_message text, published_at timestamptz, attempt_count integer not null default 0 check (attempt_count >= 0), next_attempt_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(post_id, connected_account_id), foreign key (post_id, user_id) references public.posts(id, user_id), foreign key (connected_account_id, user_id) references public.connected_accounts(id, user_id));
create table if not exists public.publishing_logs (id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, post_id uuid references public.posts(id) on delete set null, post_target_id uuid references public.post_targets(id) on delete set null, level text not null default 'info' check (level in ('info','warning','error')), event text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create index if not exists posts_due_idx on public.posts(status, scheduled_at) where status = 'scheduled';
create index if not exists post_targets_retry_idx on public.post_targets(status, next_attempt_at);
create index if not exists media_assets_user_created_idx on public.media_assets(user_id, created_at desc);
create index if not exists publishing_logs_user_created_idx on public.publishing_logs(user_id, created_at desc);
alter table public.profiles enable row level security;
alter table public.brand_settings enable row level security;
alter table public.connected_accounts enable row level security;
alter table public.media_assets enable row level security;
alter table public.posts enable row level security;
alter table public.post_targets enable row level security;
alter table public.publishing_logs enable row level security;
create policy profiles_select_own on public.profiles for select to authenticated using (id = auth.uid());
create policy profiles_update_own on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());
create policy brand_settings_select_own on public.brand_settings for select to authenticated using (user_id = auth.uid());
create policy brand_settings_insert_own on public.brand_settings for insert to authenticated with check (user_id = auth.uid());
create policy brand_settings_update_own on public.brand_settings for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
-- Intentionally no authenticated policies on connected_accounts: OAuth tokens are private and service-role Edge Functions only.
create policy media_assets_select_own on public.media_assets for select to authenticated using (user_id = auth.uid());
create policy media_assets_insert_own on public.media_assets for insert to authenticated with check (user_id = auth.uid());
create policy media_assets_update_own on public.media_assets for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy media_assets_delete_own on public.media_assets for delete to authenticated using (user_id = auth.uid());
create policy posts_select_own on public.posts for select to authenticated using (user_id = auth.uid());
create policy posts_insert_own on public.posts for insert to authenticated with check (user_id = auth.uid());
create policy posts_update_own on public.posts for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy posts_delete_own on public.posts for delete to authenticated using (user_id = auth.uid());
create policy post_targets_select_own on public.post_targets for select to authenticated using (user_id = auth.uid());
create policy post_targets_insert_own on public.post_targets for insert to authenticated with check (user_id = auth.uid());
create policy post_targets_update_own on public.post_targets for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy post_targets_delete_own on public.post_targets for delete to authenticated using (user_id = auth.uid());
create policy publishing_logs_select_own on public.publishing_logs for select to authenticated using (user_id = auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles (id, display_name, avatar_url) values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'), new.raw_user_meta_data ->> 'avatar_url') on conflict (id) do nothing; insert into public.brand_settings (user_id) values (new.id) on conflict (user_id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
